import numpy as np
from scipy import ndimage

d1_arr = np.array(demo1_input_fixed)

# Get all connected components with details
mask = d1_arr > 0
labeled, num = ndimage.label(mask)

print(f"Number of components: {num}")

# For each component, get its bounding box
components = []
for i in range(1, num + 1):
    rows, cols = np.where(labeled == i)
    components.append({
        'id': i,
        'rows': rows,
        'cols': cols,
        'box': (np.min(rows), np.min(cols), np.max(rows) - np.min(rows), np.max(cols) - np.min(cols)),
        'size': len(rows) * len(cols)
    })

for c in components:
    print(f"  {c['id']}: bbox ({c['box'][0]}, {c['box'][1]}) to ({c['box'][2]}, {c['box'][3]})=({c['box'][0]+c['box'][2]}, {c['box'][1]+c['box'][3]})")

# Visualize where each component is
# and map to 4x4 grid

h, w = d1_arr.shape
h_step, w_step = h/4, w/4

# For each component, which output cell is it in?
print("\nMapping components to output grid:")
output_membership = {}  # (out_row, out_col) -> list of component_ids

for comp in components:
    for r in comp['rows']:
        for c in comp['cols']:
            out_r = int(r / h_step)
            out_c = int(c / w_step)
            if out_r >= 0 and out_r < 4 and out_c >= 0 and out_c < 4:
                key = (out_r, out_c)
                if key not in output_membership:
                    output_membership[key] = []
                output_membership[key].append(comp['id'])

print(f"\nOutput grid occupancy:")
for i in range(4):
    for j in range(4):
        key = (i, j)
        if key in output_membership:
            print(f"  ({i},{j}): {output_membership[key]}")
        else:
            print(f"  ({i},{j}): empty")

# So output has cells with: 1 or more components
