expected = d1_arr
print(f"\nExpected output has 1s at:")
for i in range(4):
    for j in range(4):
        if expected[i, j] != 0:
            print(f"  ({i},{j})")

print(f"\nLet me match these two...")

# What determines if a cell is 1 or 0?
# Maybe: cell is 1 if there's content AND the component has some property?

# Check properties of components in cells that SHOULD be 1
print("\nComponents in EXPECTED 1-cells:")
expected_on_cells = []
for i in range(4):
    for j in range(4):
        if expected[i, j] != 0:
            key = (i, j)
            if key in output_membership:
                expected_on_cells.extend(output_membership[key])

# Now check actual components
for cid in expected_on_cells:
    for comp in components:
        if comp['id'] == cid:
            print(f"  {cid}: bbox {comp['box']}, size={comp['size']}")
            break

# Also check expected 0 cells
print("\nComponents in EXPECTED 0-cells:")
for i in range(4):
    for j in range(4):
        if expected[i, j] == 0:
            key = (i, j)
            if key in output_membership:
                for cid in output_membership[key]:
                    for comp in components:
                        if comp['id'] == cid:
                            print(f"  {cid}: bbox {comp['box']}, size={comp['size']}")
                            break

